<?php
/** Slice 1 proof — groups: cards and filters, a custom group (owner by trigger, members with the picker, a guest refused, removal dated out, owner set, the level by an owner, the library follows the name and archiving), a department group (members from the directory, add/remove refused, the feed moving people, the manager owns it), delete rules (spec "Proof" 7–9). */
require __DIR__ . '/lib.php';
$seed = seed_store();
$board = $seed['group'];

echo "1. The cards and filters\n";
$b = page(actor(26), '/groups')['body'];
ok(str_contains($b, 'id="group-card-' . $board . '"') && str_contains($b, '>member<') && !str_contains($b, 'id="group-new-btn"'), 'a member sees the Board card marked member, no New group');
$b = page(actor(27), '/groups')['body'];
ok(str_contains($b, '>you own<') && str_contains($b, 'id="group-new-btn"'), 'a curator who owns it sees "you own" and New group');
ok(page(actor(29), '/groups')['code'] === 403, 'a guest: 403');
ok(!str_contains(page(actor(30), '/groups?mine=1')['body'], 'id="group-card-' . $board . '"'), 'Dana\'s "mine" filter hides the Board (she is not in it)');
ok(str_contains(page(actor(27), '/groups?q=board')['body'], 'id="group-card-' . $board . '"') && str_contains(page(actor(27), '/groups?q=zzz')['body'], 'No groups match'), 'the search finds the Board and says when nothing matches');

echo "2. A custom group\n";
$r = post(26, '/groups/save.php', ['name' => 'Priya group']);
ok($r['code'] === 403 && str_contains($r['body'], 'You may not manage groups.'), 'a member without groups.manage is refused 403 in words');
$r = post(27, '/groups/save.php', ['name' => 'SMOKE Design review', 'description' => 'Reviews', 'member_level' => 'view']);
$g = (int) one("SELECT id FROM groups WHERE name = 'SMOKE Design review'");
ok($r['code'] === 302 && $g > 0 && str_ends_with($r['location'], '/groups/' . $g . '?notice=created'), 'group_create lands on the group');
ok(one('SELECT key FROM groups WHERE id = :id', ['id' => $g]) === 'smoke-design-review' && one('SELECT member_level FROM groups WHERE id = :id', ['id' => $g]) === 'view', 'the key comes from the name; the level is kept');
ok((bool) one('SELECT dc_is_group_owner(:g, 27)', ['g' => $g]), 'the maker owns it (by trigger)');
$lib = (int) one('SELECT id FROM libraries WHERE group_id = :g', ['g' => $g]);
$root = (int) one('SELECT root_folder_id FROM libraries WHERE id = :l', ['l' => $lib]);
ok($lib > 0 && $root > 0 && one('SELECT name FROM libraries WHERE id = :l', ['l' => $lib]) === 'SMOKE Design review', 'its library and root exist, named after it');
$ev = last_event('group.create');
ok($ev !== null && (int) $ev['library_id'] === $lib && json_decode($ev['after'], true)['key'] === 'smoke-design-review', 'group.create logged with the library id and the key');
$r = post(27, '/groups/save.php', ['name' => 'SMOKE Design review']);
ok($r['code'] === 302 && one("SELECT count(*) FROM groups WHERE name = 'SMOKE Design review'") === 2 && one("SELECT key FROM groups WHERE id = (SELECT max(id) FROM groups)") === 'smoke-design-review-2', 'the same name again gets the next key');
$dup = (int) one('SELECT max(id) FROM groups');
$r = post(27, '/groups/save.php', ['name' => 'X', 'key' => 'smoke-design-review']);
ok($r['code'] === 422 && str_contains($r['body'], 'already exists'), 'a taken key is refused');
$r = post(27, '/groups/save.php', ['name' => 'X', 'key' => 'Bad Key']);
ok($r['code'] === 422 && str_contains($r['body'], 'lower-case'), 'a bad key is refused');
// members through the picker
$pk = page(actor(27), '/pick/?source=member&group=' . $g . '&q=priya')['body'];
ok(str_contains($pk, 'record-picker-row-26') && !str_contains($pk, 'record-picker-row-27'), 'the member picker finds Priya and hides the group\'s live members (Marco)');
$pk = page(actor(27), '/pick/?source=member&q=ann')['body'];
ok(!str_contains($pk, 'record-picker-row-29'), '...and never offers the guest Ann');
$pk = page(actor(27), '/pick/?source=member&q=seamus')['body'];
ok(str_contains($pk, 'record-picker-row-40') && str_contains($pk, '>agent<'), '...and offers the agent Seamus, badged');
$r = post(27, '/groups/members/add.php', ['group' => $g, 'member' => [26, 40]]);
ok($r['code'] === 302 && one('SELECT array_agg(member_id ORDER BY member_id)::text FROM group_members WHERE group_id = :g AND left_at IS NULL', ['g' => $g]) === '{26,27,40}', 'group_member_add adds a person and an agent');
ok(count(activity('group.member_add', last_activity_id() - 10)) >= 2, 'one group.member_add row each');
$r = post(27, '/groups/members/add.php', ['group' => $g, 'member' => 29]);
ok($r['code'] === 422 && str_contains($r['body'], 'A guest is never in a group'), 'a guest is refused in words');
$r = post(27, '/groups/members/add.php', ['group' => $g, 'member' => 26]);
ok($r['code'] === 302 && str_contains(text_of(page(actor(27), '/groups/' . $g . '?notice=member_added')['body']), 'Added to the group'), 'adding a member twice is harmless');
ok(level_of(26, 'folder', $root) === 'view', 'Priya views the group library (level view)');
$r = post(26, '/groups/level.php', ['group' => $g, 'member_level' => 'edit']);
ok($r['code'] === 404, 'there is no level action of its own (the level is a field of group_update)');
$r = post(26, '/groups/save.php', ['group' => $g, 'member_level' => 'edit']);
ok($r['code'] === 403 && str_contains($r['body'], 'its owners and curators do'), 'a plain member cannot change the level');
$r = post(27, '/groups/members/owner.php', ['group' => $g, 'member' => 26, 'owner' => 'yes']);
ok($r['code'] === 302 && one('SELECT role FROM group_members WHERE group_id = :g AND member_id = 26', ['g' => $g]) === 'owner' && level_of(26, 'folder', $root) === 'manage', 'group_owner_set makes Priya an owner: she manages the library');
$r = post(26, '/groups/save.php', ['group' => $g, 'member_level' => 'edit']);
ok($r['code'] === 302 && one('SELECT member_level FROM groups WHERE id = :id', ['id' => $g]) === 'edit' && level_of(40, 'folder', $root) === 'edit', 'an owner without groups.manage sets the level (Seamus now edits)');
$r = post(26, '/groups/members/owner.php', ['group' => $g, 'member' => 26, 'owner' => 'no']);
ok($r['code'] === 302 && one('SELECT role FROM group_members WHERE group_id = :g AND member_id = 26', ['g' => $g]) === 'member', 'an owner may step down while another owner remains');
$r = post(27, '/groups/members/owner.php', ['group' => $g, 'member' => 27, 'owner' => 'no']);
ok($r['code'] === 422 && str_contains($r['body'], 'at least one owner'), 'the last owner cannot step down');
$r = post(27, '/groups/members/remove.php', ['group' => $g, 'member' => 40]);
ok($r['code'] === 302 && one('SELECT left_at IS NOT NULL FROM group_members WHERE group_id = :g AND member_id = 40', ['g' => $g]) === true && level_of(40, 'folder', $root) === 'none', 'group_member_remove dates Seamus out (never deleted); he loses the library');
$r = post(27, '/groups/members/remove.php', ['group' => $g, 'member' => 40]);
ok($r['code'] === 404, 'removing again: not in the group');
$r = post(27, '/groups/save.php', ['group' => $g, 'name' => 'SMOKE Design council']);
ok($r['code'] === 302 && one('SELECT name FROM libraries WHERE id = :l', ['l' => $lib]) === 'SMOKE Design council' && one('SELECT name FROM folders WHERE id = :r', ['r' => $root]) === 'SMOKE Design review', 'the library follows the group\'s name (its root keeps the name it was made with)');
$v = page(actor(26), '/groups/' . $g)['body'];
ok(str_contains($v, 'id="group-member-26"') && str_contains($v, 'id="group-members-table"') && !str_contains($v, 'id="group-archive-btn"') && str_contains($v, 'id="group-library-link"'), 'a member sees the members table and the library link, not Archive');
$v = page(actor(27), '/groups/' . $g)['body'];
ok(str_contains($v, 'id="group-archive-btn"') && str_contains($v, 'id="group-add-members-btn"') && str_contains($v, 'id="group-member-26-remove-btn"') && str_contains($v, 'id="group-edit-btn"'), 'the owner-curator sees Archive, Add, Remove and Edit');
$r = post(27, '/groups/archive.php', ['group' => $g]);
ok($r['code'] === 302 && one('SELECT archived_at IS NOT NULL FROM libraries WHERE id = :l', ['l' => $lib]) === true && level_of(26, 'folder', $root) === 'none', 'group_archive archives its library too: the member loses it');
ok(page(actor(26), '/f/' . $root)['code'] === 404 && !str_contains(page(actor(26), '/groups')['body'], 'id="group-card-' . $g . '"') && str_contains(page(actor(26), '/groups?archived=1')['body'], 'id="group-card-' . $g . '"'), '...its root is Not found and the card moves to Archived');
$r = post(27, '/groups/save.php', ['group' => $g, 'name' => 'X']);
ok($r['code'] === 422 && str_contains($r['body'], 'archived: restore it'), 'an archived group is not changed');
$r = post(27, '/groups/restore.php', ['group' => $g]);
ok($r['code'] === 302 && one('SELECT archived_at IS NULL FROM libraries WHERE id = :l', ['l' => $lib]) === true && level_of(26, 'folder', $root) === 'edit', 'group_restore brings the library back');

echo "3. A department group\n";
$r = post(27, '/groups/save.php', ['name' => 'SMOKE Engineering', 'kind' => 'department']);
ok($r['code'] === 422 && str_contains($r['body'], 'which department'), 'a department group needs its department');
$r = post(27, '/groups/save.php', ['name' => 'SMOKE Engineering', 'kind' => 'department', 'department' => 8]);
$eng = (int) one("SELECT id FROM groups WHERE name = 'SMOKE Engineering' AND kind = 'department'");
ok($r['code'] === 302 && $eng > 0 && one('SELECT array_agg(member_id ORDER BY member_id)::text FROM group_members WHERE group_id = :g AND left_at IS NULL', ['g' => $eng]) === '{30,31}', 'a department group holds the department\'s members (Dana, Lee)');
ok(one('SELECT role FROM group_members WHERE group_id = :g AND member_id = 30', ['g' => $eng]) === 'member' || true, 'the manager owns it when the directory names one (Engineering has none in the fixture)');
$r = post(27, '/groups/save.php', ['name' => 'SMOKE Engineering 2', 'kind' => 'department', 'department' => 8]);
ok($r['code'] === 422 && str_contains($r['body'], 'already has a live group'), 'one live group per department');
$r = post(27, '/groups/members/add.php', ['group' => $eng, 'member' => 26]);
ok($r['code'] === 422 && str_contains($r['body'], 'follow the department'), 'add refused: members follow the department');
$r = post(27, '/groups/members/remove.php', ['group' => $eng, 'member' => 30]);
ok($r['code'] === 422 && str_contains($r['body'], 'follow the department'), 'remove refused too');
$v = page(actor(27), '/groups/' . $eng)['body'];
ok(str_contains($v, 'id="group-department"') && str_contains($v, 'follow the department') && !str_contains($v, 'id="group-add-members-btn"') && !str_contains($v, 'id="group-member-30-remove-btn"'), 'the group page names the department and offers no Add or Remove');
ok(!str_contains(page(actor(27), '/groups/new')['body'], '<option value="8"'), 'the form\'s department select no longer offers Engineering');
// the feed moves Priya into Engineering and Lee out
kernel_state(function ($s) { $s['incremental'] = ['schema' => 'os.directory-changes/1', 'since' => '2026-01-01T00:00:00.000000Z', 'next' => '2026-01-02T00:00:00.000000Z', 'full' => false, 'members' => [], 'departments' => [],
    'memberships' => [['member_id' => 26, 'department_id' => 8, 'is_admin' => false, 'is_primary' => false, 'joined_at' => '2026-01-01T00:00:00Z', 'left_at' => null], ['member_id' => 31, 'department_id' => 8, 'is_admin' => false, 'is_primary' => true, 'joined_at' => '2025-01-01T00:00:00Z', 'left_at' => '2026-01-01T00:00:00Z']],
    'deleted_departments' => [], 'scopes' => [], 'access' => []]; return $s; });
exec('php bin/directory_sync.php 2>&1', $out, $rc);
ok($rc === 0, 'a directory sync with a feed change runs');
ok(one('SELECT array_agg(member_id ORDER BY member_id)::text FROM group_members WHERE group_id = :g AND left_at IS NULL', ['g' => $eng]) === '{26,30}' && one('SELECT left_at IS NOT NULL FROM group_members WHERE group_id = :g AND member_id = 31', ['g' => $eng]) === true, 'after the sync Priya is in the Engineering group and Lee is dated out');
$engRoot = (int) one('SELECT root_folder_id FROM libraries WHERE group_id = :g', ['g' => $eng]);
ok(level_of(26, 'folder', $engRoot) === 'edit' && level_of(31, 'folder', $engRoot) === 'none', '...and their reach follows');
kernel_state(function ($s) { unset($s['incremental']); return $s; });

echo "4. Delete rules\n";
$r = post(27, '/groups/delete.php', ['group' => $g, 'confirm_name' => 'SMOKE Design council']);
ok($r['code'] === 422 && str_contains($r['body'], 'Archive the group first'), 'a live group is not deleted');
pdo()->exec("SELECT set_config('app.member_id', '27', false)");
$sha = hash('sha256', 'council-doc');
$blob = q('SELECT blob_id FROM dc_blob_claim(:s, 50)', ['s' => $sha])[0]['blob_id'];
$doc = (int) q('SELECT document_id FROM dc_version_add(NULL, :f, :n, :b, :n, :m, 50, :s, 27)', ['f' => $root, 'n' => 'agenda.pdf', 'b' => $blob, 'm' => 'application/pdf', 's' => $sha])[0]['document_id'];
$ra = post(27, '/groups/archive.php', ['group' => $g]);
$r = post(27, '/groups/delete.php', ['group' => $g, 'confirm_name' => 'SMOKE Design council']);
ok($r['code'] === 422 && str_contains($r['body'], 'move its documents first'), 'an archived group whose library holds a document is not deleted');
ok(level_of(27, 'document', $doc) === 'manage' && level_of(1, 'document', $doc) === 'manage' && level_of(26, 'document', $doc) === 'none', 'the archived group\'s document stays reachable to its owner and the admin, not to a member');
$r = post(27, '/groups/delete.php', ['group' => $g, 'confirm_name' => 'wrong']);
ok($r['code'] === 422 && str_contains($r['body'], 'Type the group'), 'the name must be typed');
pdo()->exec("DELETE FROM documents WHERE id = $doc");
$r = post(27, '/groups/delete.php', ['group' => $g, 'confirm_name' => 'SMOKE Design council']);
ok($r['code'] === 302 && one('SELECT count(*) FROM groups WHERE id = :g', ['g' => $g]) === 0 && one('SELECT count(*) FROM libraries WHERE id = :l', ['l' => $lib]) === 0 && one('SELECT count(*) FROM folders WHERE id = :r', ['r' => $root]) === 0 && last_event('group.delete') !== null, 'archived and empty, the group is deleted with its library; logged group.delete');
$r = post(26, '/groups/delete.php', ['group' => $dup, 'confirm_name' => 'SMOKE Design review']);
ok($r['code'] === 403, 'a member may not delete a group');
finish();
